class Shelf {
    static class Label {
        private final int number;
        Label(int number) { this.number = number; }
        String text() { return "Shelf " + number; }
    }
}

class Main {
    public static void main(String[] args) throws Exception {
        Shelf.Label label = new Shelf.Label(4);
        System.out.println(label.text());
    }
}

class Counter {
    private final int count;
    Counter(int count) { this.count = count; }
    class View {
        int read() { return count; }
    }
}

class Main {
    public static void main(String[] args) throws Exception {
        Counter first = new Counter(3);
        Counter second = new Counter(8);
        Counter.View view = first.new View();
        System.out.println(view.read());
        System.out.println(second.new View().read());
    }
}

interface Rule { int apply(int value); }

class Main {
    public static void main(String[] args) throws Exception {
        int bonus = 5;
        class LocalRule implements Rule {
            @Override
            public int apply(int value) { return value + bonus; }
        }
        Rule doubled = new Rule() {
            @Override
            public int apply(int value) { return value * 2; }
        };
        System.out.println(new LocalRule().apply(10));
        System.out.println(doubled.apply(10));
    }
}
